function answerText(text, values) {
  for (const [id, response] of Object.entries(values)) {
    const start = `<!-- scholar:answer:${id}:start -->`, end = `<!-- /scholar:answer:${id}:end -->`;
    const first = text.indexOf(start), last = text.indexOf(end);
    assert.ok(first >= 0 && last > first, `fixture answer region ${id}`);
    const region = text.slice(first + start.length, last);
    if (region.includes("scholar:choice:")) {
      const wanted = new Set(response.split(",").map((value) => value.trim()).filter(Boolean));
      const found = new Set();
      const edited = region.replace(/^(> )?- \[[ xX]\] \*\*([^\n]+?)\*\*(.*<!-- scholar:choice:\d+ -->)$/gm, (_row, prefix, value, rest) => {
        if (wanted.has(value)) found.add(value);
        return `${prefix || ""}- [${wanted.has(value) ? "x" : " "}] **${value}**${rest}`;
      });
      assert.deepEqual(found, wanted, `fixture selected values for ${id} exist`);
      text = `${text.slice(0, first + start.length)}${edited}${text.slice(last)}`;
    } else {
      const prefix = text.slice(text.lastIndexOf("\n", first) + 1, first) === "> " ? "> " : "";
      text = `${text.slice(0, first + start.length)}\n${response.split("\n").map(line => prefix + line).join("\n")}\n${prefix}${text.slice(last)}`;
    }
  }
  return text;
}
function pdfFixture() {
  const streams = [
    "BT /F1 11 Tf 50 750 Td 18 TL (1.1 Models) Tj T* (A model approximates reality within its validity domain.) Tj T* (Transmission line models are required when rise time is comparable to flight time.) Tj ET",
    "BT /F1 11 Tf 50 750 Td (1.2 Subsequent sections.) Tj ET",
  ];
  const objects = ["<< /Type /Catalog /Pages 2 0 R >>", "<< /Type /Pages /Kids [3 0 R 5 0 R] /Count 2 >>"];
  for (let index = 0; index < streams.length; index++) {
    objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 7 0 R >> >> /Contents ${4 + index * 2} 0 R >>`);
    objects.push(`<< /Length ${Buffer.byteLength(streams[index])} >>\nstream\n${streams[index]}\nendstream`);
  }
  objects.push("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>");
  let pdf = "%PDF-1.4\n";
  const offsets = objects.map((object, index) => { const offset = Buffer.byteLength(pdf); pdf += `${index + 1} 0 obj\n${object}\nendobj\n`; return offset; });
  const xref = Buffer.byteLength(pdf);
  pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n${offsets.map(offset => `${String(offset).padStart(10, "0")} 00000 n \n`).join("")}trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;
  return Buffer.from(pdf);
}

