export async function renderPdfPage(book: ScholarBook, page: number): Promise<RenderedPdfPage> {
  validatePdfPage(book, page);
  await assertFreshSource(book);
  const rendered = await renderPdfPng(book, page);
  await assertFreshSource(book);
  return rendered;
}

