    if (!dir.isDirectory()) continue;
    for (const name of await readdir(join(root, dir.name))) if (name.endsWith(".md")) {
      const path = join(root, dir.name, name);
      if (codec.readDetails(await readFile(path, "utf8"), "book")) result.push(path);
    }
  }
  return result;
